<?php
 namespace Pterodactyl\Services\Dezerx\Billing; use Carbon\CarbonImmutable; class DemoBilling { public const PRODUCT = 'Minecraft Starter'; public const LOGO = 'https://dev-spartan.dezerx.com/storage/products/icons/CiYHDfeHF9AB8sthUeEjWM5DrO9sdT2rBCgg9qCK.webp'; public const AMOUNT = '4.99'; private const RENEWS_IN_DAYS = 5; public static function record(): array { $currency = trim((string) (Billing::all()['currency'] ?? '')); return [ 'status' => 'Active', 'product' => self::PRODUCT, 'logo' => self::LOGO, 'interval' => 'Monthly', 'price' => [ 'amount' => self::AMOUNT, 'currency' => $currency === '' ? '€' : $currency, ], 'renews_at' => CarbonImmutable::now()->addDays(self::RENEWS_IN_DAYS)->toAtomString(), 'manage_url' => '', 'invoice' => null, ]; } } 